async function listPosts(prisma, limit) {
  const posts = await prisma.post.findMany({
    take: limit,
    orderBy: { createdAt: 'desc' }
  });

  const result = [];
  for (const post of posts) {
    const author = await prisma.user.findUnique({
      where: { id: post.authorId }
    });
    result.push({ ...post, authorName: author.name });
  }
  return result;
}

const cache = new Map();

export async function getUserProfile(userId, fetchProfile) {
  if (cache.has(userId)) {
    return cache.get(userId);
  }
  const profile = await fetchProfile(userId);
  cache.set(userId, profile);
  return profile;
}

export async function updateSettings(req, res, db) {
  const updated = await db.settings.update({
    where: { userId: req.userId },
    data: req.body
  });

  db.auditLog.create({
    data: { userId: req.userId, action: 'settings.update' }
  });

  res.json(updated);
}

export async function recordView(db, postId) {
  const post = await db.post.findUnique({
    where: { id: postId },
    select: { views: true }
  });

  await db.post.update({
    where: { id: postId },
    data: { views: post.views + 1 }
  });
}

export async function chargeWithRetry(gateway, amount, userId) {
  for (let attempt = 0; attempt < 3; attempt++) {
    try {
      return await gateway.charge({ amount, userId });
    } catch (error) {
      if (attempt === 2) throw error;
      await sleep(200 * (attempt + 1));
    }
  }
}

export async function loadDashboard(api, userId) {
  const profile = await api.getProfile(userId);
  const invoices = await api.getInvoices(userId);
  const usage = await api.getUsage(userId);

  return { profile, invoices, usage };
}

export async function getPage(db, page, pageSize) {
  const skip = page * pageSize;

  const rows = await db.item.findMany({
    skip,
    take: pageSize,
    orderBy: { createdAt: 'desc' }
  });

  return rows;
}

useEffect(() => {
  function onResize() {
    setWidth(window.innerWidth);
  }

  window.addEventListener('resize', onResize);
}, []);

export async function notifyAll(mailer, recipients) {
  const sends = recipients.map((recipient) => mailer.send(recipient));

  await Promise.all(sends);
  return { sent: recipients.length };
}

export async function recentOrders(db, userId) {
  const orders = await db.order.findMany({
    orderBy: { createdAt: 'desc' }
  });

  return orders
    .filter((order) => order.userId === userId)
    .slice(0, 20);
}

export async function transfer(db, fromId, toId, amount) {
  await db.account.update({
    where: { id: fromId },
    data: { balance: { decrement: amount } }
  });

  await db.account.update({
    where: { id: toId },
    data: { balance: { increment: amount } }
  });
}

export async function getHeaderUser(db, userId) {
  const user = await db.user.findUnique({
    where: { id: userId },
    include: { posts: true, comments: true, sessions: true }
  });

  return { name: user.name, avatarUrl: user.avatarUrl };
}

export async function countActiveMembers(db, teamId) {
  const members = await db.member.count({
    where: { teamId }
  });

  return members;
}

export async function register(db, eventId, userId) {
  const existing = await db.registration.findFirst({
    where: { eventId, userId }
  });

  if (existing) return existing;

  return db.registration.create({
    data: { eventId, userId }
  });
}

export async function resizeAll(images, resize) {
  const results = await Promise.all(
    images.map((image) => resize(image))
  );

  return results;
}

export async function saveDraft(db, draft) {
  try {
    await db.draft.upsert({
      where: { id: draft.id },
      update: draft,
      create: draft
    });
  } catch (error) {
    // keep the editor responsive
  }

  return { saved: true };
}

useEffect(() => {
  const id = setInterval(() => {
    fetchStatus().then(setStatus);
  }, 2000);
}, [jobId]);

export async function fetchWithRetry(url, attempts = 5) {
  for (let i = 0; i < attempts; i++) {
    try {
      return await fetch(url);
    } catch (error) {
      if (i === attempts - 1) throw error;
    }
  }
}

export async function getQuote(items) {
  const response = await fetch('https://pricing.example.com/quote', {
    method: 'POST',
    body: JSON.stringify({ items })
  });

  return response.json();
}

export async function fetchAllPages(api) {
  const all = [];
  let page = 1;

  while (true) {
    const batch = await api.list({ page, pageSize: 50 });
    if (batch.length === 0) break;
    all.push(...batch);
    page += 1;
  }

  return all;
}

