export function cartTotal(items) {
  let total = 0;

  for (const item of items) {
    total += item.priceInRupees * item.quantity;
  }

  return total.toFixed(2);
}

function TaskList({ tasks }) {
  const sorted = tasks.sort((a, b) => a.order - b.order);

  return sorted.map((task) => <Row key={task.id} task={task} />);
}

function Price({ amount }) {
  const [label, setLabel] = useState(format(amount));

  useEffect(() => {
    setLabel(format(amount));
  }, [amount]);

  return <span>{label}</span>;
}

export async function tablePage(db, page) {
  const [rows, total] = await Promise.all([
    db.event.findMany({ skip: page * 50, take: 50 }),
    db.event.count()
  ]);

  return { rows, total, pages: Math.ceil(total / 50) };
}

export async function feedPage(db, pageNumber) {
  return db.post.findMany({
    skip: pageNumber * 20,
    take: 20,
    orderBy: { id: 'asc' }
  });
}

export async function runReport(pool, sql) {
  const client = await pool.connect();

  const result = await client.query(sql);

  client.release();
  return result.rows;
}

export async function recentApproved(db, postId) {
  return db.comment.findMany({
    where: { postId, status: 'APPROVED' },
    orderBy: { createdAt: 'desc' },
    take: 10
  });
}

export async function submitOrder(db, req, res) {
  const order = await db.order.create({
    data: { userId: req.userId, items: req.body.items }
  });

  res.json({ orderId: order.id });
}

export async function placeOrder(db, gateway, order) {
  return db.$transaction(async (tx) => {
    const created = await tx.order.create({ data: order });

    await gateway.charge({ amount: order.total });

    return tx.order.update({
      where: { id: created.id },
      data: { status: 'PAID' }
    });
  });
}

export function planSeats(response) {
  const seats = response?.data?.subscription?.seats ?? 0;

  if (seats === 0) {
    return { plan: 'free', seats: 0 };
  }

  return { plan: 'team', seats };
}

export async function runNightly(job, metrics) {
  const result = await job.run();

  metrics.record('nightly.completed', result.count);

  process.exit(0);
}

export async function dashboard(req, res, db) {
  const data = await db.dashboard.forUser(req.userId);

  res.setHeader('Cache-Control', 'public, max-age=3600');
  res.json(data);
}

export async function profile(req, res, db) {
  const user = await db.user.findUnique({
    where: { id: req.params.id }
  });

  res.json(user);
}

export async function download(req, res, storage) {
  const buffer = await storage.readAll(req.params.key);

  res.setHeader('Content-Type', 'text/csv');
  res.send(buffer);
}

function Rows({ items }) {
  return items.map((item, index) => (
    <EditableRow key={index} item={item} />
  ));
}

export function dayBucket(isoTimestamp) {
  const date = new Date(isoTimestamp);

  return date.toISOString().slice(0, 10);
}

const TAG = /^(\w+\s?)+$/;

export function isValidTag(input) {
  return TAG.test(input);
}

function Report({ rows, filter }) {
  const summary = useMemo(() => summarize(rows, filter), [rows.length]);

  return <Summary data={summary} />;
}
